const TEAM_AND_EQUIPMENT = `
-- ---------------------------------------------------------------- Pointage (§13)
-- Time comes from the server clock, never from the device. A correction never overwrites: the
-- event keeps its original time, the correction row records who changed what and why.
CREATE TABLE IF NOT EXISTS timeclock_events (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  user_name TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('in', 'break_start', 'break_end', 'out')),
  occurred_at TEXT NOT NULL,
  original_at TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'voided')),
  incoherent INTEGER NOT NULL DEFAULT 0,
  source TEXT NOT NULL CHECK (source IN ('self', 'manual')),
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_timeclock_user ON timeclock_events(user_id, occurred_at);

CREATE TABLE IF NOT EXISTS timeclock_corrections (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL REFERENCES timeclock_events(id),
  kind TEXT NOT NULL CHECK (kind IN ('edit', 'add', 'void')),
  before_at TEXT,
  after_at TEXT,
  reason TEXT NOT NULL,
  created_by_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- ---------------------------------------------------------------- Équipements (§15)
CREATE TABLE IF NOT EXISTS equipment (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  reference TEXT,
  category TEXT NOT NULL,
  serial_number TEXT,
  supplier TEXT,
  purchase_date TEXT,
  in_service_date TEXT NOT NULL,
  value_mil INTEGER NOT NULL CHECK (value_mil > 0),
  residual_mil INTEGER NOT NULL DEFAULT 0 CHECK (residual_mil >= 0),
  duration_months INTEGER NOT NULL CHECK (duration_months > 0),
  document TEXT,
  status TEXT NOT NULL CHECK (status IN ('active', 'retired')),
  retired_on TEXT,
  retired_reason TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_by TEXT,
  updated_at TEXT
);
`;

export const applyPosSchema = (db: Db): void => {
  applyFoundation(db);
  db.exec(CATALOG);
  db.exec(SERVICE);
  db.exec(CUSTOMER_SERVICES);
  db.exec(CUSTOMERS);
  db.exec(TEAM_AND_EQUIPMENT);
  applyServiceUpgrades(db);
  applyFloorDesign(db);
  applySplitBills(db);
  db.exec(INSIGHTS);
  // A register exists out of the box; more can be added from the settings.
  const hasRegister = db.prepare('SELECT 1 FROM cash_registers LIMIT 1').get();
  if (!hasRegister) {
    db.prepare('INSERT INTO cash_registers (id, name, active, created_at) VALUES (?, ?, 1, ?)').run('register-main', 'Caisse principale', new Date().toISOString());
  }
};

// ---------------------------------------------------------------- Impression, hors ligne, KDS, écrans
// Printing (print agents, printers, print jobs), offline sales, kitchen display upgrades and the
// customer-facing screens. Additive, like everything above.
const SERVICE_UPGRADES = `
-- Program installed on the register PC that prints on the café's printers (ESC/POS) and opens
-- the cash drawer. Authenticated by a token whose hash only is kept.
CREATE TABLE IF NOT EXISTS print_agents (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  version TEXT,
  last_seen_at TEXT,
  revoked_at TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL
);

-- target: 'kitchen' | 'bar' | 'register:<register id>' — what the printer prints.
CREATE TABLE IF NOT EXISTS printers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  agent_id TEXT REFERENCES print_agents(id),
  target TEXT NOT NULL,
  address TEXT NOT NULL,
  paper_width INTEGER NOT NULL DEFAULT 80 CHECK (paper_width IN (58, 80)),
  copies INTEGER NOT NULL DEFAULT 1 CHECK (copies BETWEEN 1 AND 3),
  auto_print INTEGER NOT NULL DEFAULT 1,
  cash_drawer INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  status TEXT,
  status_at TEXT,
  created_at TEXT NOT NULL
);

-- Every document to print. The content is frozen when the job is created: a later catalogue
-- change never alters a ticket already sent.
CREATE TABLE IF NOT EXISTS print_jobs (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('prep', 'bill', 'receipt', 'cancel', 'drawer', 'test')),
  target TEXT NOT NULL,
  ref_id TEXT,
  payload TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('queued', 'printing', 'printed', 'failed')),
  attempts INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  printer_id TEXT,
  duplicate_of TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  printed_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_print_jobs_queue ON print_jobs(target, status);
-- One automatic job per document (a replay never prints twice); duplicates are explicit.
CREATE UNIQUE INDEX IF NOT EXISTS idx_print_jobs_once ON print_jobs(kind, ref_id, target) WHERE duplicate_of IS NULL AND ref_id IS NOT NULL;
`;

const applyServiceUpgrades = (db: Db): void => {
  db.exec(SERVICE_UPGRADES);

  // Takeaway / counter pickup number (shown on the ticket, the prep ticket and the "ready" board).
  addColumn(db, 'pos_orders', 'pickup_number', 'pickup_number INTEGER');
  addColumn(db, 'pos_orders', 'priority', 'priority INTEGER NOT NULL DEFAULT 0');
  // Lines held back by the waiter ("à envoyer plus tard") and sent to preparation later.
  addColumn(db, 'pos_order_lines', 'fire_status', "fire_status TEXT NOT NULL DEFAULT 'now'");
  addColumn(db, 'catalog_articles', 'prep_target_minutes', 'prep_target_minutes INTEGER');
  // Sales recorded while the register was offline, synchronised later.
  addColumn(db, 'pos_sales', 'offline_ref', 'offline_ref TEXT');
  addColumn(db, 'pos_sales', 'occurred_at', 'occurred_at TEXT');
  addColumn(db, 'pos_sales', 'client_total_mil', 'client_total_mil INTEGER');

  // A held line gets its own dispatch when it is sent: an order may now have several prep tickets
  // for the same station. SQLite cannot drop a UNIQUE constraint, so the small table is rebuilt once.
  const ddl = (db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'prep_tickets'").get() as { sql: string } | undefined)?.sql ?? '';
  if (ddl.includes('UNIQUE (order_id, destination)')) {
    db.transaction(() => {
      db.exec(`
        CREATE TABLE prep_tickets_new (
          id TEXT PRIMARY KEY,
          order_id TEXT NOT NULL REFERENCES pos_orders(id),
          destination TEXT NOT NULL CHECK (destination IN ('kitchen', 'bar')),
          label TEXT NOT NULL,
          sent_at TEXT NOT NULL
        );
        INSERT INTO prep_tickets_new (id, order_id, destination, label, sent_at) SELECT id, order_id, destination, label, sent_at FROM prep_tickets;
        DROP TABLE prep_tickets;
        ALTER TABLE prep_tickets_new RENAME TO prep_tickets;
        CREATE INDEX IF NOT EXISTS idx_prep_tickets_order ON prep_tickets(order_id);
      `);
    })();
  }
};

// --- Floor designer (amélioration 01): architecture, decor, 3D assets and plan versions ----------
const FLOOR_DESIGN = `
CREATE TABLE IF NOT EXISTS floor_elements (
  id TEXT PRIMARY KEY,
  area_id TEXT NOT NULL REFERENCES floor_areas(id),
  kind TEXT NOT NULL CHECK (kind IN ('wall', 'door', 'window', 'counter', 'bar', 'column', 'bench', 'plant', 'stairs', 'zone', 'decor', 'model')),
  label TEXT,
  x INTEGER NOT NULL,
  y INTEGER NOT NULL,
  width INTEGER NOT NULL CHECK (width > 0),
  height INTEGER NOT NULL CHECK (height > 0),
  rotation INTEGER NOT NULL DEFAULT 0,
  elevation_cm INTEGER NOT NULL DEFAULT 0,
  color TEXT,
  material TEXT,
  asset_id TEXT,
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_floor_elements_area ON floor_elements(area_id) WHERE archived_at IS NULL;

-- Library of textures, 3D models (glTF/GLB) and background plans: a CDN link or an uploaded file
-- (kept in the database so the nightly backup carries it).
CREATE TABLE IF NOT EXISTS floor_assets (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('texture', 'model', 'background')),
  name TEXT NOT NULL,
  url TEXT,
  mime_type TEXT,
  size_bytes INTEGER,
  data BLOB,
  tile_cm INTEGER,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  archived_at TEXT,
  CHECK (url IS NOT NULL OR data IS NOT NULL)
);

-- Named versions of the plan ("été avec terrasse", "hiver"): a snapshot of geometry, decor and
-- table positions that can be re-applied.
CREATE TABLE IF NOT EXISTS floor_versions (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  snapshot TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  applied_at TEXT
);
`;

const applyFloorDesign = (db: Db): void => {
  db.exec(FLOOR_DESIGN);
  addColumn(db, 'floor_areas', 'width_cm', 'width_cm INTEGER');
  addColumn(db, 'floor_areas', 'depth_cm', 'depth_cm INTEGER');
  addColumn(db, 'floor_areas', 'floor_material', "floor_material TEXT NOT NULL DEFAULT 'parquet'");
  addColumn(db, 'floor_areas', 'wall_color', "wall_color TEXT NOT NULL DEFAULT '#e9e1d6'");
  addColumn(db, 'floor_areas', 'wall_height_cm', 'wall_height_cm INTEGER NOT NULL DEFAULT 280');
  addColumn(db, 'floor_areas', 'background_asset_id', 'background_asset_id TEXT');
  addColumn(db, 'floor_areas', 'background_opacity', 'background_opacity REAL NOT NULL DEFAULT 0.5');
  addColumn(db, 'floor_areas', 'background_scale', 'background_scale REAL NOT NULL DEFAULT 1');
  addColumn(db, 'floor_areas', 'background_x', 'background_x INTEGER NOT NULL DEFAULT 0');
  addColumn(db, 'floor_areas', 'background_y', 'background_y INTEGER NOT NULL DEFAULT 0');
  addColumn(db, 'dining_tables', 'chairs', 'chairs INTEGER');
  addColumn(db, 'dining_tables', 'material', 'material TEXT');
};

// --- Split bill (amélioration 08): one bill, several payers -----------------------------------------
const SPLIT_BILLS = `
CREATE TABLE IF NOT EXISTS sale_splits (
  id TEXT PRIMARY KEY,
  sale_id TEXT NOT NULL REFERENCES pos_sales(id),
  part INTEGER NOT NULL,
  parts INTEGER NOT NULL,
  mode TEXT NOT NULL CHECK (mode IN ('items', 'equal', 'amount')),
  label TEXT,
  amount_mil INTEGER NOT NULL CHECK (amount_mil >= 0),
  paid_mil INTEGER NOT NULL DEFAULT 0,
  line_ids TEXT NOT NULL DEFAULT '[]',
  customer_id TEXT REFERENCES customers(id),
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE (sale_id, part)
);
`;

const applySplitBills = (db: Db): void => {
  db.exec(SPLIT_BILLS);
  addColumn(db, 'pos_payments', 'split_id', 'split_id TEXT');
  // Points are earned once per sale, or once per part when the bill is split between payers.
  addColumn(db, 'loyalty_ledger', 'split_id', 'split_id TEXT');
  db.exec(`DROP INDEX IF EXISTS idx_loyalty_one_earn_per_sale;
    CREATE UNIQUE INDEX IF NOT EXISTS idx_loyalty_one_earn_per_part ON loyalty_ledger(sale_id, COALESCE(split_id, '')) WHERE type = 'earn';`);
};

// --- Pilotage (amélioration 09): supplier pack size and lead time per stock product ---------------
const INSIGHTS = `
CREATE TABLE IF NOT EXISTS stock_reorder_settings (
  product_id TEXT PRIMARY KEY,
  pack_size REAL,
  lead_days INTEGER,
  updated_by TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
`;
